.form-control:focus {
    background: transparent;
    border: none;
}
.verification-code-wrapper{
    width: 480px;
    padding: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 5px;
    background-color: #fff;
    border: 1px solid #ebebeb
}
.verification-area{
    width: 100%;
}
.verification-code {
    display: flex;
    position: relative;
    z-index: 1;
    height: 50px;
    width: 100%;
}
.verification-code::after {
    position: absolute;
    content: '';
    right: -37px;
    width: 35px;
    height: 50px;
    background-color: #fff;
    z-index: 2;
}
.verification-code input {
    position: absolute;
    height: 50px;
    width: calc(100% + 80px);
    left: 0;
    background: transparent;
    font-size: 25px !important;
    font-weight: 800;
    letter-spacing: 51px;
    text-indent: 1px;
    border: none;
    z-index: 1;
    padding-left: 25px;
    font-family: 'Courier Prime', monospace;
    color: #504c4c !important;
}
.verification-code input:focus {
    outline: none;
    cursor: pointer;
    box-shadow: none;
    background-color: transparent;
}
.boxes {
    position: absolute;
    top: 0;
    height: 100%;
    width: 100%;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    z-index: -1;
}
.verification-code span {
    height: 50px;
    width: calc((100% / 6) - 3px);
    background: #f1f1f1;
    border: solid 1px #f1f1f1;
    text-align: center;
    line-height: 50px;
    color: #cdc8c8
}
.verification-text{
    font-size: 1.2rem;
}
@media (max-width: 575px) {
    .verification-code-wrapper {
        width: 400px;
        padding: 32px;
    }

    .verification-code input {
        width: calc(100% + 35px);
        padding-left: 18px;
        letter-spacing: 41px;
    }

    .verification-text{
        font-size: 1rem;
    }

    .verification-code::after {
        right: -32px;
        width: 30px;
    }
}
@media (max-width: 450px) {
    .verification-code-wrapper {
        width: 380px;
        padding: 32px;
    }

    .verification-code input {
        width: calc(100% + 45px);
        padding-left: 15px;
        letter-spacing: 38px;
    }
}
@media (max-width: 400px) {
    .verification-code {
        height: 40px;
    }
    
    .verification-code-wrapper {
        width: 340px;
        padding: 32px;
    }

    .verification-code input {
        width: calc(100% + 40px);
        padding-left: 15px;
        letter-spacing: 34px;
        height: 40px;
    }

    .verification-code span {
        height: 40px;
        line-height: 40px;
    }

    .verification-code::after {
        height: 40px;
    }

    .verification-code input {
        font-size: 20px !important;
    }
}
@media (max-width: 375px) {
    .verification-code-wrapper {
        width: 300px;
        padding: 32px;
    }

    .verification-code input {
        padding-left: 13px;
        letter-spacing: 27px;
        height: 40px;
    }
}
/* Inter is loaded from layout (rsms.me/inter/inter.css) — avoid extra Google Fonts round-trip */
/* Flexible base: rem/clamp so layout does not break on zoom or different base font */
:root {
    --fs-base: 1rem;
    --lh-body: 1.625;
    --space-xs: 0.25rem;
    --space-sm: 0.5rem;
    --space-md: 1rem;
    --space-lg: 1.5rem;
    --container-max: min(100%, 75rem);
}
html {
    scroll-behavior: smooth;
}
body {
    padding: 0;
    margin: 0;
    font-size: var(--fs-base);
    color: #555555;
    line-height: var(--lh-body);
    overflow-x: hidden;
    font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    background: #F7FBFE;
}
h1,
h2,
h3,
h4,
h5,
h6 {
    font-weight: 500;
    margin: 0;
    line-height: 1.3;
    color: #0b254a;
    font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
h1 a,
h2 a,
h3 a,
h4 a,
h5 a,
h6 a {
    color: #0b254a;
}
h1 a:hover,
h2 a:hover,
h3 a:hover,
h4 a:hover,
h5 a:hover,
h6 a:hover {
    color: #4FC4F7;
}
h1 {
    font-size: clamp(1.75rem, 4vw, 3rem);
    font-weight: 600;
}
h2 {
    font-size: clamp(1.5rem, 3vw, 2.25rem);
    margin-top: -0.4375rem;
    font-weight: 600;
}
h3 {
    font-size: clamp(1.25rem, 2.5vw, 1.75rem);
    margin-top: -0.375rem;
    font-weight: 600;
}
h4 {
    font-size: clamp(1.125rem, 2vw, 1.5rem);
    margin-top: -0.3125rem;
}
h5 {
    font-size: clamp(1rem, 1.5vw, 1.25rem);
    margin-top: -0.25rem;
}
h6 {
    font-size: clamp(0.9375rem, 1.2vw, 1.125rem);
    margin-top: -0.1875rem;
}
@media (min-width: 768px) {
    h1 {
        font-size: 76px;
        line-height: 86px;
        margin-top: -16px;
    }

    h2 {
        font-size: 54px;
        line-height: 64px;
        margin-top: -7px;
    }

    h3 {
        font-size: 36px;
        line-height: 46px;
        margin-top: -4px;
    }

    h4 {
        font-size: 30px;
        margin-top: -5px;
    }

    h5 {
        font-size: 24px;
        margin-top: -4px;
    }

    h6 {
        font-size: 20px;
        margin-top: -3px;
    }
}
a {
    display: inline-block;
    transition: all ease 0.3s;
}
a:hover {
    text-decoration: none;
    color: inherit;
}
ul {
    margin: 0;
    padding: 0;
}
ul li {
    list-style: none;
    padding: 5px 0;
}
.bg_img {
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
}
.bg_fixed {
    background-attachment: fixed;
}
.top__center {
    background-position: top center;
}
.color-tooltip::before {
    position: absolute;
    content: "";
}
.widget__post,
.widget.widget__tags ul,
.post__tag,
.post__share,
.review-item .content .entry-meta,
.review-item,
.widget-check-group,
.contact__item,
.deposit-item,
.deposit-preview,
.social--icons,
.dashboard__header-top-right,
.dashboard__header-top,
.profile-wrapper,
.reply-item,
.header-wrapper,
.social-icons {
    display: flex;
    flex-wrap: wrap;
}
.video-button,
.widget-check-color input:checked+label::before,
.widget-check-color label img,
.widget-check-color label,
.about-thumb .video__btn {
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    position: absolute;
    content: "";
}
.pt-120 {
    padding-top: 80px;
}
.pb-120 {
    padding-bottom: 80px;
}
.pt-80 {
    padding-top: 90px;
}
.pb-80 {
    padding-bottom: 90px;
}
.pt-60 {
    padding-top: 45px;
}
.pb-60 {
    padding-bottom: 45px;
}
@media (min-width: 992px) {
    .pt-120 {
        padding-top: 120px;
    }

    .pb-120 {
        padding-bottom: 120px;
    }

    .pt-60 {
        padding-top: 60px;
    }

    .pb-60 {
        padding-bottom: 60px;
    }
}
/*Section Header*/
label,
button,
input[type=submit] {
    cursor: pointer;
}
body *::-webkit-scrollbar-track {
    box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);
    background-color: #F5F5F5;
}
body *::-webkit-scrollbar {
    width: 6px;
    height: 4px;
    background-color: #4FC4F7;
}
body *::-webkit-scrollbar-button {
    background-color: #4FC4F7;
}
body *::-webkit-scrollbar-thumb {
    background-color: #4FC4F7;
}
*::-moz-selection {
    background-color: #4FC4F7;
    color: #fff;
}
*::selection {
    background-color: #4FC4F7;
    color: #fff;
}
.overlay {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    background: rgba(11, 37, 74, 0.7);
    z-index: 9999;
    visibility: hidden;
    opacity: 0;
    transition: all ease 0.3s;
}
body:has(#user-dashboard-root) .overlay {
    z-index: 99899;
}
body:has(#user-dashboard-root) .overlay.active {
    opacity: 0.42;
}
.overlay.active {
    opacity: 1;
    visibility: visible;
