    margin-bottom: 0;
}
.table th {
    font-size: 0.75rem;
    text-align: center;
}
.table td {
    font-size: 0.875rem;
    color: #5b6e88;
    text-align: center;
}
.table td span,
.table td p,
.table td li {
    font-size: 0.875rem;
}
table th:last-child {
    text-align: right;
}
table th:first-child {
    text-align: left;
}
table td:last-child {
    text-align: right;
}
table td:first-child {
    text-align: left;
}
table tbody tr:last-child td {
    border: none;
}
.table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(115, 115, 115, 0.05);
}
[data-label] {
    position: relative;
}
[data-label]::before {
    position: absolute;
    content: attr(data-label);
    font-weight: 500;
    color: #000000;
    top: 0;
    left: 0;
    padding: 13px 15px;
    display: none;
}
@media (max-width: 767px) {
    .table-responsive--sm thead {
        display: none;
    }


    .table-responsive--sm tbody tr:nth-child(even) {
        background-color: #F4F4F5;
    }

    .table-responsive--sm tr th,
    .table-responsive--sm tr td {
        display: block;
        padding-left: 45%;
        text-align: right !important;
    }

    .table-responsive--sm [data-label]::before {
        display: block;
    }

    table tbody tr:last-child td {
        border-bottom: 1px solid #dee2e6;
    }

    table tbody tr:last-child td:last-child {
        border: none;
    }
}
@media (max-width: 575px) {
    .table-responsive--xs thead {
        display: none;
    }

    .table-responsive--xs tbody tr:nth-child(odd) {
        background-color: #f5f5f5;
    }

    .table-responsive--xs tr th,
    .table-responsive--xs tr td {
        display: block;
        padding-left: 45%;
        text-align: right !important;
    }

    .table-responsive--xs [data-label]::before {
        display: block;
    }

    table tbody tr:last-child td {
        border-bottom: 1px solid #dee2e6;
    }

    table tbody tr:last-child td:last-child {
        border: none;
    }
}
@media (max-width: 320px) {
    .timer {
        font-size: 17px;
    }

    .bal {
        font-size: 23px;
    }
}
