.copyInput {
     display: inline-block;
     line-height: 50px;
     position: absolute;
     top: 0;
     right: 0;
     width: 40px;
     text-align: center;
     font-size: 14px;
     cursor: pointer;
     transition: all .3s;
 }
.copied::after {
     position: absolute;
     top: 50%;
     transform: translateY(-50%);
     right: 12%;
     width: 100px;
     display: block;
     content: "COPIED";
     font-size: 12px;
     padding: 5px 5px;
     color: #fff;
     background-color: #FF7000;
     border-radius: 3px;
     opacity: 0;
     will-change: opacity, transform;
     animation: showcopied 1.5s ease;
     -webkit-transform: translateY(-50%);
     -moz-transform: translateY(-50%);
     -ms-transform: translateY(-50%);
     -o-transform: translateY(-50%);
}
@keyframes showcopied {
    0% {
        opacity: 0;
        transform: translateX(100%) translateY(-50%);
        -webkit-transform: translateX(100%) translateY(-50%);
        -moz-transform: translateX(100%) translateY(-50%);
        -ms-transform: translateX(100%) translateY(-50%);
        -o-transform: translateX(100%) translateY(-50%);
    }

    50% {
        opacity: 0.7;
        transform: translateX(40%) translateY(-50%);
        -webkit-transform: translateX(40%) translateY(-50%);
        -moz-transform: translateX(40%) translateY(-50%);
        -ms-transform: translateX(40%) translateY(-50%);
        -o-transform: translateX(40%) translateY(-50%);
    }

    70% {
        opacity: 1;
        transform: translateX(0) translateY(-50%);
        -webkit-transform: translateX(0) translateY(-50%);
        -moz-transform: translateX(0) translateY(-50%);
        -ms-transform: translateX(0) translateY(-50%);
        -o-transform: translateX(0) translateY(-50%);
    }

    100% {
        opacity: 0;
    }
 }
/* Banner overlay: animation from admin banner animation_type */
.banner-slide-inner[data-animation-type="fade"] .banner-overlay { animation: bannerOverlayFade 0.6s ease both; }
.banner-slide-inner[data-animation-type="slide"] .banner-overlay { animation: bannerOverlaySlide 0.5s ease both; }
.banner-slide-inner[data-animation-type="bounce"] .banner-overlay { animation: bannerOverlayBounce 0.6s ease both; }
.banner-slide-inner[data-animation-type="zoom"] .banner-overlay { animation: bannerOverlayZoom 0.5s ease both; }
.banner-slide-inner[data-animation-type="fadeInUp"] .banner-overlay { animation: bannerOverlayFadeUp 0.5s ease both; }
@keyframes bannerOverlayFade { from { opacity: 0; } to { opacity: 1; } }
@keyframes bannerOverlaySlide { from { opacity: 0; transform: translateX(-20px); } to { opacity: 1; transform: translateX(0); } }
@keyframes bannerOverlayBounce { from { opacity: 0; transform: scale(0.9); } to { opacity: 1; transform: scale(1); } }
@keyframes bannerOverlayZoom { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
@keyframes bannerOverlayFadeUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
