    min-height: 100vh;
    background: rgba(255, 255, 255, 0.98);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    box-shadow: 4px 0 40px rgba(0, 0, 0, 0.12), 0 0 1px rgba(0, 0, 0, 0.08);
    padding: 0;
    overflow-y: auto;
    overflow-x: hidden;
    transform: translateX(-100%);
    transition: transform 0.2s cubic-bezier(0.32, 0.72, 0, 1);
    -webkit-overflow-scrolling: touch;
    /* Safe area for notched devices (iPhone X, etc.) */
    padding-top: env(safe-area-inset-top, 0);
    padding-bottom: env(safe-area-inset-bottom, 0);
}
.glass-mobile-menu.active .glass-mobile-menu-content {
    transform: translateX(0);
}
/* Sidebar Header - Close + Title - Always visible at top */
.glass-mobile-menu-header {
    position: sticky;
    top: 0;
    left: 0;
    right: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: calc(12px + env(safe-area-inset-top, 0)) 16px 12px;
    background: rgba(255, 255, 255, 0.95);
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
    z-index: 2;
    flex-shrink: 0;
}
.glass-mobile-menu-close {
    width: 42px;
    height: 42px;
    min-width: 42px;
    border: none;
    background: rgba(0, 0, 0, 0.05);
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 22px;
    color: #333;
    transition: all 0.25s ease;
}
.glass-mobile-menu-close:hover {
    background: rgba(255, 107, 107, 0.12);
    color: #ff6b6b;
    transform: scale(1.02);
}
.glass-mobile-menu-close:active {
    transform: scale(0.97);
}
.glass-mobile-menu-title {
    font-size: 16px;
    font-weight: 700;
    color: #1a1a1a;
    letter-spacing: 0.02em;
}
/* Search in Sidebar */
.glass-mobile-search {
    padding: 16px;
    flex-shrink: 0;
}
/* Inline pill search (input + submit inside .glass-mobile-search-inner) */
.glass-mobile-search form.glass-mobile-search-form {
    display: block;
    width: 100%;
    margin: 0;
}
.glass-mobile-search form:not(.glass-mobile-search-form) {
    display: flex;
    gap: 10px;
    align-items: center;
}
.glass-mobile-search input:not(.glass-mobile-search-input) {
    flex: 1;
    padding: 12px 16px;
    border: 1.5px solid rgba(0, 0, 0, 0.08);
    border-radius: 12px;
    outline: none;
    font-size: 15px;
    transition: border-color 0.2s;
}
.glass-mobile-search input:not(.glass-mobile-search-input):focus {
    border-color: var(--main, #4FC4F7);
    box-shadow: 0 0 0 3px rgba(79, 196, 247, 0.15);
}
.glass-mobile-search button:not(.glass-mobile-search-submit) {
    width: 46px;
    height: 46px;
    min-width: 46px;
