    border-radius: 12px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    transition: transform 0.2s;
}
.glass-mobile-search button:not(.glass-mobile-search-submit):hover {
