/**
 * Scroll Bar / Headline Ticker - TV-style, professional.
 * Static asset: safe to cache (CSS). Served from assets/ with long cache headers.
 */
/* ~2mm gap above and below bar on all positions */
.scrollbar-section {
    margin: 0;
    padding: 6px 0;
    width: 100%;
    min-height: 0;
    display: flex;
    align-items: center;
}
.scrollbar-section--banner_below {
    margin-top: 0;
    padding: 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
}
/* Keep banner ticker running and flush under banner */
.scrollbar-section--banner_below .scrollbar-content {
    animation-play-state: running !important;
}
.scrollbar-section--footer_above,
.scrollbar-section--header_above,
.scrollbar-section--content_top,
.scrollbar-section--content_bottom,
.scrollbar-section--footer_below,
.scrollbar-section--product_listing_above,
.scrollbar-section--product_listing_below,
.scrollbar-section--category_above,
.scrollbar-section--category_below,
.scrollbar-section--product_detail_above,
.scrollbar-section--product_detail_below,
.scrollbar-section--custom { padding: 6px 0; }
/* হেডার ↔ মেইন / ব্যানার: উপরে ফাঁক নয়; নিচে সামান্য শ্বাস */
.scrollbar-section--header_below {
    padding: 0 0 6px;
}
/* মেইনের প্রথম টিকার: উপরে ফাঁক নয় (হেডার-পরবর্তী লাইন ↔ ব্যানার) */
main > .scrollbar-section--content_top:first-of-type {
    padding-top: 0;
}
/* Outer: full width, no side padding so bar is truly full width and centered */
.scrollbar-bar-outer {
    width: 100%;
    max-width: 100%;
    padding-left: 0 !important;
    padding-right: 0 !important;
}
.scrollbar-wrapper {
    width: 100%;
    max-width: 100%;
    overflow: hidden;
    padding: 8px 16px;
    line-height: 1.4;
    min-height: 52px; /* overridden by inline style from bar_height (8–120px) */
    display: flex;
    align-items: center;
    box-sizing: border-box;
    margin-left: auto;
    margin-right: auto;
}
/* Bar size: minimal padding so bar stays thin when bar_height is 8–24px */
