/* ===== GLOBAL FLOATING GLASS CONTACT PANEL ===== */
/* Variables – override these to theme without breaking layout (flexible, future-proof) */
.contact-live-chat-module,
.contact-panel-glass {
    --cp-radius: 16px;
    --cp-radius-inner: 16px;
    --cp-gap: clamp(6px, 1.5vw, 10px);
    --cp-pad: clamp(8px, 2vw, 12px);
    --cp-body-bg: #faf9f8;
    --cp-msg-bg: #e5ddd5;
    --cp-shadow: 0 6px 24px rgba(0, 0, 0, 0.06);
    --cp-border: 1px solid rgba(0, 0, 0, 0.04);
    --cp-transition: 0.2s ease-out;
}
/* Backdrop – lightweight blur */
.contact-panel-backdrop {
    position: fixed;
    inset: 0;
    z-index: 2147483644;
    background: rgba(0, 0, 0, 0.32);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    opacity: 0;
    visibility: hidden;
    transition: opacity var(--cp-transition, 0.2s), visibility var(--cp-transition, 0.2s);
}
.contact-panel-backdrop.is-open {
    opacity: 1;
    visibility: visible;
}
/* ===== ভাসমান লাইভ চ্যাট – flexible, হালকা, ভাঙে না ===== */
.contact-panel-glass {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: min(400px, calc(100vw - var(--cp-gap, 24px) * 2));
    min-width: min(280px, 100vw);
    max-width: calc(100vw - var(--cp-gap, 24px) * 2);
    height: min(85vh, 720px);
    min-height: min(360px, 85vh);
    max-height: calc(100vh - var(--cp-gap, 24px) * 2);
    z-index: 2147483645;
    border-radius: var(--cp-radius);
    overflow: hidden;
    opacity: 0;
    visibility: hidden;
    transition: opacity var(--cp-transition), visibility var(--cp-transition), transform var(--cp-transition);
    pointer-events: none;
    box-shadow: var(--cp-shadow), var(--cp-border);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    isolation: isolate;
    contain: layout style paint;
}
.contact-panel-glass.is-open {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
}
.contact-panel-glass-inner {
    position: relative;
    width: 100%;
    height: 100%;
    min-height: 0;
    border-radius: var(--cp-radius-inner);
    background: var(--cp-body-bg);
    box-shadow: inset var(--cp-border);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    flex: 1 1 0;
}
