        opacity: 1;
    }

    50% {
        opacity: 0.7;
    }
}
.contact-panel-close {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.06);
    color: #374151;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    transition: background 0.2s, color 0.2s;
}
.contact-panel-close:hover {
    background: rgba(0, 0, 0, 0.1);
    color: #1a1a2e;
}
.contact-panel-body {
    padding: 6px 8px 10px;
    background: #f0f2f5;
    flex: 1 1 0;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    -webkit-overflow-scrolling: touch;
    display: flex;
