/* রিং অ্যানিমেশন – চোখে পড়ে */
.contact-float-btn::before {
    content: '';
    position: absolute;
    inset: -8px;
    border-radius: 50%;
    border: 2px solid rgba(37, 211, 102, 0.5);
    animation: contact-float-ring 2s ease-out infinite;
    pointer-events: none;
}
.contact-float-btn--effect::after {
    content: '';
    position: absolute;
    inset: -8px;
    border-radius: 50%;
    border: 2px solid rgba(0, 136, 204, 0.4);
    animation: contact-float-ring 2s ease-out infinite;
    animation-delay: 1s;
    pointer-events: none;
    z-index: -1;
}
@keyframes contact-float-ring {
    0% {
        transform: scale(0.85);
        opacity: 0.8;
    }

    100% {
        transform: scale(1.5);
        opacity: 0;
    }
}
