/* Product sections: always ONE row per category; overflow = horizontal scroll or auto-scroll carousel */
/* Default home sections: no horizontal bleed on mobile */
.product-carousel-section { min-width: 0; }
.product-carousel-section > .w-full { min-width: 0; max-width: 100%; box-sizing: border-box; }
.product-carousel-section:not(.product-carousel-section--active) .product-carousel-wrap {
    max-width: 100%;
    min-width: 0;
    overflow-x: hidden;
    box-sizing: border-box;
}
.product-carousel-section:not(.product-carousel-section--active) .product-carousel-track {
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
}
/* ---- Auto-scroll carousel (--active): single row ONLY via flexbox (no grid wrap) ---- */
.product-carousel-section--active .product-carousel-wrap {
    overflow: hidden;
    position: relative;
    width: 100%;
    touch-action: pan-y pinch-zoom;
    --per-row: 1;
}
@media (min-width: 320px) {
    .product-carousel-section--active .product-carousel-wrap { --per-row: 2; }
}
@media (min-width: 640px) {
    .product-carousel-section--active .product-carousel-wrap { --per-row: 4; }
}
@media (min-width: 768px) {
    .product-carousel-section--active .product-carousel-wrap { --per-row: 4; }
}
@media (min-width: 1024px) {
    .product-carousel-section--active .product-carousel-wrap { --per-row: 5; }
}
@media (min-width: 1280px) {
    .product-carousel-section--active .product-carousel-wrap { --per-row: 6; }
}
.product-carousel-section--active .product-carousel-track {
    overflow: visible;
    width: 100%;
}
/* Flexbox: one row only; item width = 1/N of track; track width = (cols / per-row) * 100% */
.product-carousel-section--active .product-carousel-track-inner {
    display: flex;
    flex-wrap: nowrap;
    flex-direction: row;
    flex-shrink: 0;
    align-items: stretch;
    will-change: transform;
    backface-visibility: hidden;
    transform: translateZ(0);
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-sizing: border-box;
    width: calc(var(--carousel-cols, 24) / var(--per-row, 6) * 100%);
}
.product-carousel-section--active .product-carousel-wrap.is-dragging .product-carousel-track-inner,
.product-carousel-section--active .product-carousel-wrap.is-paused .product-carousel-track-inner {
    transition-duration: 0.1s;
}
/* Each item = 1 column; fixed basis so one row never wraps */
.product-carousel-section--active .product-carousel__item {
    flex: 0 0 calc(100% / var(--carousel-cols, 24));
    width: calc(100% / var(--carousel-cols, 24));
    min-width: 0;
    box-sizing: border-box;
}
.product-carousel-section--active .product-carousel__item .product-card {
    width: 100%;
    height: auto;
    min-height: 0;
}
/* ---- Single row with manual horizontal scroll (--scroll-only): one line, no wrap; full card height visible ---- */
.product-carousel-section--scroll-only .product-carousel-wrap {
    overflow-x: auto;
    overflow-y: visible;
    width: 100%;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
    scrollbar-color: rgba(17, 24, 39, 0.35) rgba(17, 24, 39, 0.10);
}
.product-carousel-section--scroll-only .product-carousel-track {
    width: 100%;
    overflow: visible;
}
.product-carousel-section--scroll-only .product-carousel-track-inner {
    display: flex;
    flex-wrap: nowrap;
    align-items: flex-start;
    gap: 1mm;
    width: -moz-max-content;
    width: max-content;
    min-width: 100%;
    padding-bottom: 4px;
    box-sizing: border-box;
}
/* Shared horizontal scrollbar styling (usable outside carousels too) */
.h-scrollbar {
    scrollbar-width: thin;
    scrollbar-color: rgba(17, 24, 39, 0.35) rgba(17, 24, 39, 0.10);
}
.h-scrollbar::-webkit-scrollbar {
    height: 8px;
}
.h-scrollbar::-webkit-scrollbar-track {
    background: rgba(17, 24, 39, 0.10);
    border-radius: 999px;
}
.h-scrollbar::-webkit-scrollbar-thumb {
    background: rgba(17, 24, 39, 0.35);
    border-radius: 999px;
}
.h-scrollbar::-webkit-scrollbar-thumb:hover {
    background: rgba(17, 24, 39, 0.50);
}
/* Keep manual scroll, hide visible scrollbar bar */
.product-carousel-section--scroll-only .product-carousel-wrap,
.h-scrollbar {
    scrollbar-width: none;
    -ms-overflow-style: none;
}
.product-carousel-section--scroll-only .product-carousel-wrap::-webkit-scrollbar,
.h-scrollbar::-webkit-scrollbar {
    width: 0;
    height: 0;
    display: none;
}
.product-carousel-section--scroll-only .product-carousel__item {
    flex: 0 0 auto;
    box-sizing: border-box;
    min-width: 0;
}
/* Visible per row: mobile 2, tablet 3-4, laptop 5, desktop 6, wide 7, ultra-wide 8 */
@media (max-width: 319.98px) {
