  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92) 0%, rgba(238, 242, 255, 0.75) 100%);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-top: 1px solid rgba(199, 210, 254, 0.35);
  border-bottom: 1px solid rgba(226, 232, 240, 0.8);
  padding: 0.45rem 0;
}
.promo-features-grid {
  display: flex !important;
  flex-wrap: nowrap !important;
  gap: 0.5rem;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  margin: 0;
  padding: 0;
}
.promo-features-grid::-webkit-scrollbar {
  display: none;
}
.promo-feature-card {
  flex: 0 0 calc(25% - 0.375rem);
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.45rem 0.55rem;
  background: #fff;
  border: 1px solid #e2e4e8;
  border-radius: 8px;
  text-decoration: none;
  color: inherit;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.05);
  transition: box-shadow 0.25s ease, border-color 0.25s ease;
}
.promo-feature-card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  border-color: #d0d3d8;
}
.promo-feature-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.promo-feature-icon img {
  width: 100%;
  height: 100%;
  -o-object-fit: contain;
     object-fit: contain;
}
.promo-feature-content {
  flex: 1;
  min-width: 0;
}
.promo-feature-title {
  font-size: 0.78rem;
  font-weight: 700;
  color: #0d2137;
  line-height: 1.3;
  margin: 0 0 0.12rem 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.promo-feature-desc {
  font-size: 0.68rem;
  color: #6b7280;
  margin: 0;
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
/* মোবাইল ও ট্যাব – একই লাইনে ৪টা, প্রতিটি কার্ড আলাদা */
@media (max-width: 991px) {
  .promo-features-bar {
    padding: 0.4rem 0;
  }

  .promo-features-grid {
    gap: 0.45rem;
  }

  .promo-feature-card {
    padding: 0.4rem 0.5rem;
    gap: 0.45rem;
  }

  .promo-feature-icon {
    width: 28px;
    height: 28px;
  }

  .promo-feature-title {
    font-size: 0.74rem;
  }

  .promo-feature-desc {
    font-size: 0.65rem;
  }
}
@media (max-width: 575px) {
  .promo-features-bar {
    padding: 0.35rem 0;
  }

  .promo-features-grid {
    gap: 0.35rem;
  }

  .promo-feature-card {
    padding: 0.35rem 0.4rem;
    gap: 0.35rem;
  }

  .promo-feature-icon {
    width: 26px;
    height: 26px;
  }

  .promo-feature-title {
    font-size: 0.72rem;
    -webkit-line-clamp: 2;
  }

  .promo-feature-desc {
    display: none;
  }
}
