/**
 * StayLBD – User Dashboard Module (BEM-style)
 * Loaded only on /user/* and /ticket pages. No conflict with global CSS.
 * Z-index: Sidebar (top) > Overlay (middle) > Content. No full blackout.
 */
/* ---- Variables ---- (সাইডবার কম্প্যাক্ট, ২মিমি/৫মিমি গ্যাপ) */
.dashboard-section {
    --dash-sidebar-w: 220px;
    --dash-overlay-z: 99998;
    --dash-sidebar-z: 100002;
    --dash-transition: 0.25s ease;
}
/* Override main.css .dashboard__sidebar .side__menu__area { overflow: hidden } – scrollable so ALL menu items visible, no clipping */
#user-dashboard-root .dashboard__sidebar .side__menu__area {
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch;
    min-height: 0;
}
#user-dashboard-root .dashboard__sidebar.active .side__menu__area {
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch;
}
/* ---- Overlay: dashboard only – behind sidebar, light dim (no full blackout) ---- */
body:has(#user-dashboard-root) .overlay {
    z-index: var(--dash-overlay-z);
    pointer-events: none;
    cursor: default;
    background: rgba(0, 0, 0, 0.35);
}
body:has(#user-dashboard-root) .overlay.active {
    pointer-events: auto;
    cursor: pointer;
    opacity: 1;
    visibility: visible;
    background: rgba(0, 0, 0, 0.35);
}
/* Override main.css .overlay.active { opacity: 1 } so we keep light dim on dashboard */
body:has(#user-dashboard-root) .overlay.active {
    opacity: 0.4 !important;
    background: rgba(0, 0, 0, 0.4) !important;
}
/* ---- Body scroll lock when sidebar open (mobile/tablet) ---- */
body.dashboard-sidebar-open {
    overflow: hidden !important;
    position: fixed;
    width: 100%;
    height: 100%;
}
/* Overlay BELOW dashboard section so sidebar is always on top (no “only dark” screen) */
body.dashboard-sidebar-open .overlay.active {
    z-index: 99900 !important;
    visibility: visible !important;
    opacity: 0.4 !important;
    pointer-events: auto !important;
    left: var(--dash-sidebar-w, 220px) !important;
}
/* প্রোফাইল সাইডবার খোলা থাকলে: সেকশন ওভারলের উপরে, সাইডবার সবার উপরে ভাসমান */
body.dashboard-sidebar-open .dashboard-section {
    position: relative;
    z-index: 100100 !important;
    isolation: isolate;
}
body.dashboard-sidebar-open .dashboard-content-col {
    z-index: 0 !important;
}
body.dashboard-sidebar-open .dashboard__sidebar.active {
    z-index: 999999 !important;
    pointer-events: auto !important;
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    touch-action: manipulation;
}
body.dashboard-sidebar-open .dashboard__sidebar.active,
body.dashboard-sidebar-open .dashboard__sidebar.active a,
body.dashboard-sidebar-open .dashboard__sidebar.active button,
body.dashboard-sidebar-open .dashboard__sidebar.active form button,
body.dashboard-sidebar-open .dashboard__sidebar.active .side__menu li a,
body.dashboard-sidebar-open .dashboard__sidebar.active .side__menu__logout-btn {
    pointer-events: auto !important;
    cursor: pointer;
}
@media (min-width: 992px) {
    body.dashboard-sidebar-open {
        overflow: visible !important;
        position: static;
        width: auto;
        height: auto;
    }
