/* Compare Page – responsive, optimized. Breakpoints: 380, 576, 768, 992, 1200px */
.compare-page {
    background: linear-gradient(180deg, #f8f9fc 0%, #f0f2f6 100%);
    min-height: 0;
    padding: 0.5rem 0 1.5rem;
    width: 100%;
    max-width: 100%;
    contain: layout style;
}
.compare-page__container,
.compare-page .container {
    width: 100%;
    max-width: 100%;
    padding: 0 0.5rem;
    box-sizing: border-box;
}
.compare-toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
}
/* Table (desktop xl only) */
.compare-table-wrap {
    width: 100%;
