    word-break: break-word;
}
.compare-page .compare-compact-table tbody td.dashboard-compact-name,
.compare-page .compare-compact-table .dashboard-list-name-link {
    max-width: 100%;
    overflow-wrap: break-word;
    word-break: break-word;
}
.compare-page .compare-table-img-link {
    width: 72px;
    height: 72px;
    min-width: 72px;
    min-height: 72px;
}
.compare-page .compare-table-img-link img { width: 100%; height: 100%; -o-object-fit: cover; object-fit: cover; }
/* Mobile cards: CSS vars – one base, overrides per breakpoint */
.compare-mobile-cards {
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0;
    --cmp-mb: 0;
    --cmp-pad: 0.08rem 0.18rem;
