    --cmp-img: 72px;
    --cmp-name-fs: 0.76rem;
    --cmp-meta-fs: 0.56rem;
    --cmp-price-fs: 0.76rem;
    --cmp-badge-fs: 0.46rem;
    --cmp-btn-h: 24px;
    --cmp-btn-pad: 0.06rem 0.14rem;
    --cmp-btn-fs: 0.6rem;
    --cmp-actions-gap: 0.05rem;
    --cmp-rating-fs: 0.48rem;
}
.compare-mobile-card {
    background: var(--list-page-card-bg, #fff);
    border: 1px solid var(--list-page-border, #e5e7eb);
    border-radius: var(--list-page-radius, 8px);
    box-shadow: var(--list-page-shadow, 0 1px 3px rgba(0,0,0,0.06));
    overflow: hidden;
    margin: 0;
}
.compare-mobile-card:not(:last-child) { margin-bottom: var(--cmp-mb) !important; }
.compare-mobile-card__body { padding: var(--cmp-pad) !important; margin: 0 !important; }
.compare-mobile-card__inner { gap: var(--cmp-gap); display: flex; align-items: flex-start; }
.compare-mobile-card__content { min-width: 0; flex: 1 1 auto; }
.compare-mobile-card__img {
    flex-shrink: 0;
    width: var(--cmp-img);
    height: var(--cmp-img);
    min-width: var(--cmp-img);
    min-height: var(--cmp-img);
    border-radius: 6px;
}
.compare-mobile-card__img img { -o-object-fit: cover; object-fit: cover; }
.compare-mobile-card__name {
    font-size: var(--cmp-name-fs);
    line-height: 1.15;
    word-break: break-word;
    overflow-wrap: break-word;
    margin-bottom: 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}
.compare-mobile-card__meta {
    font-size: var(--cmp-meta-fs);
