.compare-mobile-card__meta > span { white-space: normal; }
.compare-mobile-card__meta .compare-mobile-card__best-badge { margin-left: 0.15rem; flex-shrink: 0; }
.compare-mobile-card__price-row { margin-bottom: 0; }
.compare-mobile-card__price { font-size: var(--cmp-price-fs); white-space: nowrap; }
.compare-mobile-card__best-badge { font-size: var(--cmp-badge-fs); }
.compare-mobile-card__actions { gap: var(--cmp-actions-gap); flex-wrap: wrap; }
.compare-mobile-card__actions .list-page-action-btn,
.compare-mobile-card__actions .btn {
    min-height: var(--cmp-btn-h);
    padding: var(--cmp-btn-pad);
    font-size: var(--cmp-btn-fs);
    line-height: 1.15;
    flex: 1 1 auto;
    min-width: 0;
}
.compare-mobile-card .ratings,
.compare-mobile-card .ratings i { font-size: var(--cmp-rating-fs); }
.compare-page .list-page-empty {
    background: var(--list-page-card-bg, #fff);
    border: 1px solid var(--list-page-border, #e5e7eb);
    border-radius: var(--list-page-radius, 8px);
}
/* Container padding by viewport */
@media (min-width: 576px) {
    .compare-page .container { padding-left: 0.75rem; padding-right: 0.75rem; }
}
@media (min-width: 768px) {
    .compare-page .container { padding: 0 1rem; max-width: 1400px; margin: 0 auto; }
}
/* Toolbar: tablet & below */
@media (max-width: 1199.98px) {
    .compare-page .compare-toolbar { margin-bottom: 0.5rem !important; gap: 0.35rem; }
    .compare-toolbar .badge { padding: 0.3rem 0.5rem !important; font-size: 0.8rem; }
    .compare-toolbar .btn { padding: 0.3rem 0.5rem; font-size: 0.8rem; }
}
@media (max-width: 575.98px) {
    .compare-toolbar { flex-direction: column; align-items: stretch; }
    .compare-toolbar .btn, .compare-toolbar .badge { justify-content: center; }
}
@media (max-width: 380px) {
