    .compare-toolbar .btn { font-size: 0.75rem; padding: 0.3rem 0.5rem; }
}
/* Desktop XL (≥1200px): table visible, card scroll, action buttons */
@media (min-width: 1200px) {
    .compare-page .compare-table-card {
        overflow-x: auto !important;
        overflow-y: visible;
        -webkit-overflow-scrolling: touch;
        min-width: 0;
        max-width: 100%;
