    .compare-page .card.border-0.shadow-sm.rounded-3.d-xl-block,
    #dashboard-ajax-content .compare-page .card.border-0.shadow-sm.rounded-3.d-xl-block,
    #user-dashboard-root .compare-page .card.border-0.shadow-sm.rounded-3.d-xl-block {
        display: block !important;
        visibility: visible !important;
    }
    #dashboard-ajax-content .compare-page .compare-table-wrap,
    #user-dashboard-root .compare-page .compare-table-wrap {
        display: block !important;
        visibility: visible !important;
    }
    .compare-page .compare-compact-table { display: table !important; }
}
@media (max-width: 991.98px) {
    .compare-compact-table { min-width: 600px; }
}
/* Mobile cards: 992–1199 (tablet) */
@media (min-width: 992px) and (max-width: 1199.98px) {
    .compare-mobile-cards {
        --cmp-pad: 0.06rem 0.16rem;
        --cmp-gap: 0.08rem;
