        --cmp-btn-fs: 0.62rem;
    }
    .compare-mobile-card__name { -webkit-line-clamp: 1; }
}
/* 768–991 (small tablet) */
@media (max-width: 991.98px) {
    .compare-mobile-cards {
        --cmp-pad: 0.06rem 0.16rem;
        --cmp-gap: 0.08rem;
        --cmp-img: 74px;
