        --cmp-price-fs: 0.74rem;
        --cmp-btn-h: 24px;
        --cmp-btn-fs: 0.58rem;
    }
    .compare-mobile-card__name { -webkit-line-clamp: 1; }
}
/* 576–767 (large phone) */
@media (max-width: 767.98px) {
    .compare-mobile-cards {
        --cmp-pad: 0.05rem 0.14rem;
        --cmp-gap: 0.08rem;
        --cmp-img: 70px;
        --cmp-name-fs: 0.72rem;
        --cmp-meta-fs: 0.52rem;
        --cmp-price-fs: 0.72rem;
        --cmp-btn-pad: 0.05rem 0.12rem;
        --cmp-btn-fs: 0.56rem;
        --cmp-rating-fs: 0.46rem;
        --cmp-actions-gap: 0.04rem;
    }
    .compare-mobile-card__name { -webkit-line-clamp: 1; }
}
/* ≤575 (phone) */
@media (max-width: 575.98px) {
    .compare-mobile-cards {
        --cmp-pad: 0.04rem 0.12rem;
        --cmp-gap: 0.06rem;
        --cmp-img: 66px;
        --cmp-name-fs: 0.7rem;
        --cmp-meta-fs: 0.5rem;
        --cmp-price-fs: 0.7rem;
        --cmp-btn-h: 22px;
        --cmp-btn-pad: 0.04rem 0.1rem;
        --cmp-btn-fs: 0.54rem;
        --cmp-actions-gap: 0.04rem;
    }
