}
/* ≤380 (extra small) */
@media (max-width: 380px) {
    .compare-mobile-cards {
        --cmp-pad: 0.04rem 0.1rem;
        --cmp-gap: 0.05rem;
        --cmp-img: 60px;
        --cmp-name-fs: 0.66rem;
